// 12-20's 'Damazti Cluster' (enemy_1542_wdslm, PRTS “变形者集群”), its Isomorphic Fragments (_2 and _3; PRTS 同构碎片1
// and 同构碎片2), the decoy fragment (_4; PRTS 同构碎片3) and the Deconstructed Distortion (enemy_1323_wdbshd, 解构畸变体).
// Runtime: server/sim/content/arkpedia-enemy-damazti.js. Each record, native closure, template and projectile is pinned
// below; the boss clips come from data/arkpedia-damazti-animations.json. Both levels are pinned (level 1 is read over
// level 0). A stage may set the host's P1SummonHLevel.hlevel_mark to 1 (H12-3/H12-4 adverse): a second first-form
// fragment then arrives on branch_3 at 25% HP.
//
// Native program (enemy_wdslm[...] / enemy_wdslmSTD[...] templates, standRegisterList):
// - Disguise: the host and _2 are spies (civilianModeTalent + pretending: the chapter-12 identification). While any
//   group member is undetected every member holds an invincibleStack (INVINCIBLE). Completion casts SwitchMode (Die,
//   2 s) into the first form (P1).
// - Group: _2/_3 registerSelf to the live host and take its HP ratio. splitDamage: after damage, every other member is
//   set to the damaged member's HP ratio. reduceDamage: Physical and Arts damage taken x (1 - 0.2 x live fragments).
//   killAll: a member that finishes (dies for good or leaks) finishes the rest (skipReborn). syncReborn: a member at
//   0 HP knocks out the others with it (each revives if it still can).
// - P1: melee 2_Attack (OnAttack 1.33 of 2.67 s). syncAttackP1 (icd 10, cd 20): 2_Skill, OnAttack 1.83; one ally
//   anywhere (global range, CREATED_TIME_DES with taunt first), ATK x atk_scale Physical on that tile; every fragment
//   is forced to cast its own. Below 50% HP (first time): branch_2's fragment (_2, disguised) on its preset route and
//   2 s INVINCIBLE for the group (summonInvincible).
// - Revive (reborn, once; host and _2): 30 s at full HP afterwards; every second (first at 0.9 s) 100 sourceless Arts to
//   each selectable ally within 1.75 (not camouflaged/invisible). The host's revive releases the wave when it ends
//   (finish_current_wave_when_buff_finish; PRTS: 重生结束时，释放当前波次). Then P2 with 5 s INVINCIBLE.
// - P2: syncAttackP2 (icd 10, cd 20) as in P1. syncAttackWithSummon, Lifeline Burst (icd 0, cd 50): 2_Skill_2
//   (9.1 s, OnAttack 7.97): at the cast start the tile of every ally on the field is locked (camouflaged ones excepted);
//   at OnAttack each lock deals fixedValueDamage (375) Arts to every ally on it and its 4 neighbours (x-5) and summons a
//   Distortion on it (SummonEnemiesOnTargetTile, FLY). Fragments play the clip with no effect.
//   halfHPSummon (P2HPRatioChecker every 0.1 s, below 50% once): marks one operator (no tokens/traps) preferring one
//   with no operator in its 3x3 square (standAloneFlag, x-4), then the latest deployed; the group is INVINCIBLE for 20 s.
//   After the 15 s mark, or as soon as the operator leaves the field: its card can no longer deploy (UNDEPLOYABLE,
//   ALL_THE_TIME), the decoy (_4) appears on its tile, and the operator is removed (InstantKill).
// - Decoy (_4): FLY, INVINCIBLE, unmovable, no attack; 2 s later, if a host lives, branch_1's fragment (_3) on its
//   preset route; then it leaves (suicideAndSummon).
// - Distortion: loses 250 HP every second (enemy_wdsdw[loss_hp], PURE, first after 1 s). Its Corrosion comes from the
//   stage rune (apply_elemental_damage), so a stage with this family must carry it (damaztiStageRuleOk).
//
// Readings settled by PRTS where the data was ambiguous: the mark lasts 15 s (the skill's
// enemy_wdslm[dieAndSummon].duration, not the buff's lifeTime 5); _2's sync attack is 100% ATK (its talent's
// syncAttackP1.atk_scale 1.5 does not reach the skill); the wave is released when the revive ends.
// [INFERRED] Lifeline Burst detonates at 2_Skill_2's OnAttack (7.97 s); PRTS says "about 6 s". Projectile flight is
// not modelled (SyncAtk and p2s2 reach at once; the Distortion's own shot is an ordinary ranged attack).
import clocks from '../../data/arkpedia-damazti-animations.json' with { type: 'json' };
import distortionClocks from '../../data/arkpedia-distortion-animations.json' with { type: 'json' };
import { DETECT } from './enemy-norport-identity-features.js';

const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const norm=v=>Array.isArray(v)?v.map(norm):v&&typeof v==="object"?("m_PathID"in v&&Object.keys(v).length===2?{ref:v.m_PathID==="0"?null:v.m_FileID===0?"local":"ext:"+v.m_PathID}
 :Object.fromEntries(Object.entries(v).filter(([k])=>!["m_GameObject","m_Name","m_Father","m_Children"].includes(k)).map(([k,x])=>[k,norm(x)]))):v;
const refs=v=>Array.isArray(v)?v.flatMap(refs):v&&typeof v==="object"?("m_PathID"in v&&v.m_FileID===0&&v.m_PathID!=="0"&&Object.keys(v).length===2?[v]
 :Object.entries(v).filter(([k])=>k!=="m_GameObject").flatMap(([,x])=>refs(x))):[];
function closure(n){
 const seen=new Set(),todo=Object.values(n).flat();
 while(todo.length){const c=todo.pop();if(!c||seen.has(c))continue;seen.add(c);todo.push(...n.$siblings(c),...refs(c).map(r=>n.$ref(r)).filter(Boolean));}
 return [...seen].map(c=>JSON.stringify(norm(c))).sort();
}
