export const isDamaztiCluster=r=>pinnedRecord(r)&&DAMAZTI_FAMILY.includes(r.prefabKey);
export const isDamaztiDecoy=r=>pinnedRecord(r)&&r.prefabKey===DECOY_ID;
export const isDistortion=r=>pinnedRecord(r)&&r.prefabKey===DISTORTION_ID;

const F=Math.fround;
// The boss skeleton's reviewed clips (every fragment shares it).
const CLIPS={"2_Attack":[F(8/3),F(4/3)],"2_Skill":[F(11/3),F(11/6)],"2_Skill_2":[F(9.1),F(239/30)],Die:[2,null],"2_Die_Begin":[1,null],"2_Die_End":[1,null]};
const clockOk=(r,n)=>{
 const root=n[r.prefabKey]?.find(v=>"_modes"in v),graphic=n.$ref(root?._animator);
 const clock=r.prefabKey===DISTORTION_ID?distortionClocks.enemies[DISTORTION_ID]:clocks.enemies[HOST_ID];
 if(!clock||n.$ref(graphic?._skeleton)?.skeletonDataAsset?.m_PathID!==clock.source?.skeletonDataPathId)return false;
 if(r.prefabKey===DISTORTION_ID)return clock.durations.Attack===1&&same(clock.events.Attack?.filter(e=>e.name==="OnAttack").map(e=>e.time),[F(.4)]);
 return Object.entries(CLIPS).every(([k,[dur,hit]])=>clock.durations[k]===dur
  &&(hit==null||same(clock.events[k]?.filter(e=>e.name==="OnAttack").map(e=>e.time),[hit])))
  &&["Move","Idle","2_Move","2_Idle","2_Die_2"].every(k=>clock.durations[k]>0);
};
/** Exact pinned record (per level), native closure, templates, projectiles and clips. */
export function damaztiNative(r,n){
 const pin=PINS[r?.prefabKey],x=pin?.levels[r?.level];
 if(!pinnedRecord(r)||r.notCountInTotal||r.applyWay!==x.applyWay||Object.entries(x.stats).some(([k,v])=>!same(r.stats[k],v))
  ||!same(r.talents,x.talents)||!same(r.skills,x.skills)||!same(r.abilities,x.abilities)||!same(r.sp??null,x.sp))return false;
 if(r.prefabKey===HOST_ID&&overlayTalents(r).bb["P1SummonHLevel.hlevel_mark"]!==0)return false;
 if(!same(closure(n),pin.spec)||Object.entries(pin.templates).some(([k,v])=>!same(n.$template(k),v))
  ||Object.entries(pin.projectiles).some(([k,v])=>!same(n.$projectile(k).map(c=>JSON.stringify(norm(c))).sort(),v)))return false;
 return clockOk(r,n);
}

// Level 1 (H12, TN-2) lists only what differs; it is read over level zero (talents by key, skills by prefab key).
function overlayTalents(r){
 const L0=PINS[r.prefabKey].levels[0].talents,bb={...L0.bb,...r.talents.bb},bbStr={...L0.bbStr,...r.talents.bbStr},groups={};
 for(const k of Object.keys({...bb,...bbStr})){const i=k.indexOf("."),g=i>0?k.slice(0,i):k;(groups[g]??=[]).push(i>0?k.slice(i+1):"");}
 for(const g of Object.values(groups))g.sort();
 return {bb,bbStr,groups};
}
const overlaySkills=r=>PINS[r.prefabKey].levels[0].skills.map(s=>r.skills.find(x=>x.prefabKey===s.prefabKey)??s);
const C=()=>clocks.enemies[HOST_ID];
const clip=k=>({dur:C().durations[k],hit:C().events[k].find(e=>e.name==="OnAttack").time});
// x-5 (the burst's projectile range) and the 0.9 s / 1 s revive damage clock, read from the pinned components.
const X5=Object.freeze([[1,0],[0,-1],[0,0],[0,1],[-1,0]]);
export function damaztiParams(r){
 const {bb:t,bbStr:ts}=overlayTalents(r),skills=overlaySkills(r),sk=k=>skills.find(s=>s.prefabKey===k),key=r.prefabKey;
 const host=key===HOST_ID,disguised=key!=="enemy_1542_wdslm_3",d=C().durations;
 const sync=(k,cd)=>({...clip("2_Skill"),scale:sk(k).bb.atk_scale,cooldown:cd?sk(k).cooldown:0,initial:cd?sk(k).initCooldown:0});
 const burst=sk("syncAttackWithSummon"),half=sk("halfHPSummon");
 return {role:host?"host":"stand",resistance:t["reduceDamage.damage_resistance_base"],
  identity:disguised?{detect:DETECT,switchDur:d.Die,move:null,atkScale:null,invisible:null,attackAnim:null,
   clips:{disguised:{move:"Move",idle:"Idle",die:"Die"},revealed:{move:"2_Move",idle:"2_Idle",die:"2_Die_2"},switch:"Die"}}:null,
  attack:clip("2_Attack"),
  sync:{p1:sync("syncAttackP1",host),p2:sync("syncAttackP2",host)},
  burst:host?{lock:true,...clip("2_Skill_2"),damage:burst.bb.fixedValueDamage,cooldown:burst.cooldown,initial:burst.initCooldown,area:X5,summon:DISTORTION_ID}
   :{lock:false,dur:d["2_Skill_2"]},
  reborn:Number.isFinite(t["reborn.duration"])?{available:true,duration:t["reborn.duration"],dot:t["reborn.dotDamageValue"],radius:t["reborn.range_radius"],
   interval:1,first:F(.9),invincible:t["P2Passive.rebornInvincible_time"],hpRatio:1}:{available:false},
  ...(host?{summon:{ratio:t["P1SummonStand.hp_ratio"],branch:ts["P1SummonStand.branch_id"],action:t["P1SummonStand.action_index"],invincible:2},
   // p1SummonHLevel: the same summon, armed only when the stage sets hlevel_mark (IsBlackboardZero, IfNot).
   hard:t["P1SummonHLevel.hlevel_mark"]!==0?{ratio:t["P1SummonHLevel.hp_ratio"],branch:ts["P1SummonHLevel.branch_id"],action:t["P1SummonHLevel.action_index"]}:null,
   half:{ratio:t["P2HalfHPFlag.hp_ratio"],mark:half.bb["enemy_wdslm[dieAndSummon].duration"],invincible:half.bb["enemy_wdslm[P2halfHpInvincible].duration"],decoy:DECOY_ID}}:{}),
  clips:{sync:"2_Skill",burst:"2_Skill_2",rebornBegin:d["2_Die_Begin"],rebornEnd:d["2_Die_End"]}};
}
export const damaztiDecoyParams=r=>{const {bb,bbStr}=overlayTalents(r);return {delay:2,branch:bbStr["suicideAndSummon.branch_id"],action:bb["suicideAndSummon.action_index"],host:HOST_ID};};
export const distortionParams=r=>({loss:overlayTalents(r).bb["lossHP.value"],interval:1});

/** A stage with the family must give all of them (and the Distortion) the reviewed Corrosion rune. */
export function damaztiStageRuleOk(rules){
 const m=rules?.enemyElementalDamage;
 return !!m&&DAMAZTI_RUNE_TARGETS.filter(id=>id!==DECOY_ID).every(id=>m[id]?.element==="erosion"&&m[id].ratio>0);
}

const TEXTS=HOST.levels[0].abilities.map(a=>a.text);
const DISTORTION_TEXTS=DISTORTION.levels[0].abilities.map(a=>a.text);
const cluster={matchesRecord:isDamaztiCluster,covers:damaztiNative};
const ROLE_CLAIMS={enemy_1542_wdslm:{wrappers:4,active:1},enemy_1542_wdslm_2:{wrappers:3,active:1},enemy_1542_wdslm_3:{wrappers:2,active:0}};
export const DAMAZTI_FEATURES={
 // Every member carries skill:syncAttackWithSummon at both levels (level 1 is sparse), so it holds the runtime, the
 // native claims, the spawns and the handbook lines.
 "skill:syncAttackWithSummon":{...cluster,ability:{kind:"damaztiCluster",params:damaztiParams},explains:text=>TEXTS.includes(text),
  nativeClaim:(p,n)=>ROLE_CLAIMS[Object.keys(ROLE_CLAIMS).find(k=>Object.hasOwn(n,k))]??null,
  dependsOn:r=>r.prefabKey===HOST_ID?["enemy_1542_wdslm_2","enemy_1542_wdslm_3",DECOY_ID,DISTORTION_ID]:[],
  stageSparseTalents:r=>r.level===1?overlayTalents(r):null,stageSparseSkills:r=>overlaySkills(r),
  // H12-3/H12-4 adverse arm the hard-level summon; any other value is refused.
  stageOverrides:{"P1SummonHLevel.hlevel_mark":v=>v===0||v===1},
  // A stage list naming some of the skills changes those in place (sparse overlay) and keeps the others.
  stageSkillSetOverride:(r,keys)=>keys.every(k=>PINS[r.prefabKey].levels[0].skills.some(x=>x.prefabKey===k)),
  // H12-4 adverse: Lifeline Burst every 35 s instead of 50. Values only; the skill is the reviewed one.
  stageSkillTimingOverrides:{syncAttackWithSummon:{cooldown:v=>Number.isFinite(v)&&v>=10&&v<=50}},
  note:"'Damazti Cluster' group: shared HP, damage reduction per fragment, group invincibility while disguised, two forms, revive, Lifeline Burst, the half-HP mark"},
 "talent:reduceDamage":{...cluster,note:"damage reduction per fragment (skill:syncAttackWithSummon)"},
 "talent:P1SummonStand":{...cluster,note:"first-form fragment summon (skill:syncAttackWithSummon)"},
 "talent:P1SummonHLevel":{...cluster,note:"hard-level summon on branch_3 when a stage sets hlevel_mark 1 (skill:syncAttackWithSummon)"},
 "talent:P2Passive":{...cluster,note:"5 s INVINCIBLE entering the second form (skill:syncAttackWithSummon)"},
 "talent:reborn":{...cluster,note:"the 30 s revive and its Arts aura (skill:syncAttackWithSummon)"},
 "talent:P2HalfHPFlag":{...cluster,note:"second-form half-HP trigger (skill:syncAttackWithSummon)"},
 "talent:syncAttackP1":{...cluster,note:"does not reach the fragment's sync attack (PRTS: 100%) (skill:syncAttackWithSummon)"},
 "skill:syncAttackP1":{...cluster,note:"run by skill:syncAttackWithSummon"},
 "skill:syncAttackP2":{...cluster,note:"run by skill:syncAttackWithSummon"},
 "skill:halfHPSummon":{...cluster,note:"the half-HP mark, run by skill:syncAttackWithSummon"},
 "talent:suicideAndSummon":{matchesRecord:isDamaztiDecoy,covers:damaztiNative,ability:{kind:"damaztiDecoy",params:damaztiDecoyParams},
  dependsOn:()=>["enemy_1542_wdslm_3"],note:"decoy fragment: 2 s, then the last fragment on its preset route"},
 "talent:lossHP":{matchesRecord:isDistortion,covers:damaztiNative,ability:{kind:"distortionDecay",params:distortionParams},
  explains:text=>DISTORTION_TEXTS.includes(text),note:"loses 250 HP per second; Corrosion from the stage rune"},
};

/** Stage branches this family drives (SummonEnemiesFollowBranchRoute): the host's first-form summon (P1SummonStand)
 * and the decoy's last fragment (suicideAndSummon). A hard level (hlevel_mark != 0) also names P1SummonHLevel's. */
export function damaztiBranchBindings(level){
 const refs=level?.enemyDbRefs??[],out=[];
 for(const ref of refs){
  if(![HOST_ID,DECOY_ID].includes(ref.id))continue;
  const base=PINS[ref.id].levels[0].talents,over=ref.overwrittenData?.talentBlackboard;
  const value=k=>{const row=Array.isArray(over)?over.find(x=>x.key===k):null;return row?(row.valueStr??row.value):(base.bbStr[k]??base.bb[k]);};
  if(ref.id===HOST_ID){out.push(value("P1SummonStand.branch_id"));if(value("P1SummonHLevel.hlevel_mark")!==0)out.push(value("P1SummonHLevel.branch_id"));}
  else out.push(value("suicideAndSummon.branch_id"));
 }
 return out;
}
